const ALIASES = {
  'close': 'x', 'add': 'plus', 'agent': 'bot', 'agents': 'bot', 'connections': 'plug', 'marketplace': 'store',
  'projects': 'folder', 'start': 'sparkles', 'circle-help': 'help', 'question': 'help', 'undo-2': 'undo',
  'refresh-cw': 'refresh', 'square': 'stop', 'edit': 'pencil', 'delete': 'trash', 'chart': 'bar-chart',
  'xray': 'scan-eye', 'x-ray': 'scan-eye', 'note': 'sticky-note', 'deploy': 'rocket', 'publish': 'rocket',
  'error': 'alert-circle', 'warning': 'alert-triangle', 'success': 'check-circle', 'money': 'coins', 'credits': 'coins',
  'package': 'box', 'component': 'blocks', 'git': 'git-branch', 'pr': 'git-pull-request', 'doctor': 'stethoscope',
  'test': 'flask', 'budget': 'wallet', 'guardrails': 'shield-check', 'knowledge': 'book-open', 'memory': 'brain', 'model': 'cpu',
  'trigger': 'zap', 'schedule': 'clock', 'email': 'mail', 'chat': 'message-square', 'voice': 'mic', 'domain': 'globe',
};

const warned = new Set();
/** Register additional icons (inner SVG markup) from a feature module. */
export function registerIcons(map) { Object.assign(ICONS, map); }
export function hasIcon(name) { return !!(ICONS[name] || ICONS[ALIASES[name]]); }

/** <Icon name="check" size=${16} /> — inherits currentColor. */
export function Icon({ name, size = 16, stroke = 2, class: cls = '', style, title }) {
  const key = ICONS[name] ? name : ALIASES[name];
  let inner = ICONS[key];
  if (!inner) {
    if (name && !warned.has(name)) { warned.add(name); console.warn(`[icons] unknown icon "${name}"`); }
    inner = ICONS['circle-dashed'];
  }
  return html`<svg class=${'icon ' + cls} style=${style} width=${size} height=${size} viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width=${stroke} stroke-linecap="round" stroke-linejoin="round" aria-hidden=${title ? undefined : 'true'} role=${title ? 'img' : undefined} dangerouslySetInnerHTML=${{ __html: (title ? `<title>${title}</title>` : '') + inner }}></svg>`;
}

export const iconNames = () => Object.keys(ICONS);
